        r = 0
        while r < h:
            if grid[r][c] == bg:
                r += 1
                continue
            color, a = grid[r][c], r
            while r + 1 < h and grid[r + 1][c] == color:
                r += 1
            for x in range(a, r + 1):
                perimeter.add((x, c))
            if r - a + 1 >= 2:
                bars.append(("v", c, a, r))
            r += 1

    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != bg and (r, c) not in perimeter]
    if not markers:
        return g

    marker_cells = {(r, c) for r, c, _ in markers}
    for r, c, _ in markers:
        g[r][c] = 4

    for orient in ("h", "v"):
        group = [b for b in bars if b[0] == orient]
        if not group:
            continue

        # Marker offsets within the span of a boundary bar are repeated
        # on all parallel boundary bars.
        offsets = set()
        for r, c, _ in markers:
            pos = c if orient == "h" else r
            for b in group:
                a, end = b[2], b[3]
                if a <= pos <= end:
                    offsets.add(pos - a)
                    break

        for typ, fixed, a, end in group:
            inward = 1 if fixed == 0 else -1
            for off in offsets:
                lane = a + off
                if lane > end:
                    continue
                if typ == "h":
                    r, c = fixed + inward, lane
                    while 0 <= r < h:
                        if (r, c) in marker_cells or grid[r][c] != bg:
                            break
                        g[r][c] = markers[0][2]
